def get_values(self, profile, bitarray, status):
        """ Get keys and values from bitarray """
        keys = []
        values = []
        for key, value in self.dict.items():
            if key in status:
                bitarray.set(value)
                keys.append(key)
                values.append(status[key])
            else:
                bitarray.unset(value)
        return keys, values

